#include <stdio.h>

int suma(int valores[], int cantidad) {
    int total = 0;
    for (int i = 0; i < cantidad; i++) {
        total += valores[i];
    }
    return total;
}

int main(void) {
    int datos[] = {1, 2, 3, 4};
    printf("%d\n", suma(datos, 4));
    return 0;
}

#include <stdio.h>

int factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

int main(void) {
    printf("%d\n", factorial(5));
    return 0;
}

#include <stdio.h>

void cuenta(int n) {
    if (n == 0) {
        printf("Fin\n");
        return;
    }
    printf("%d ", n);
    cuenta(n - 1);
}

int main(void) {
    cuenta(3);
    return 0;
}
